test_cases.assertion_pseudocode:
from afissues.protocol import IssueResult
import dataclasses
assert dataclasses.is_dataclass(IssueResult)
fields = {f.name for f in dataclasses.fields(IssueResult)}
assert fields == {'number', 'title', 'html_url', 'body', 'labels'}
issue = IssueResult(number=1, title='t', html_url='u', body='b', labels=['l1'])
assert issue.number == 1
try:
    issue.number = 2
    assert False, 'should be frozen'
except dataclasses.FrozenInstanceError:
    pass

from afissues.protocol import IssueComment
import dataclasses
assert dataclasses.is_dataclass(IssueComment)
fields = {f.name for f in dataclasses.fields(IssueComment)}
assert fields == {'id', 'body', 'user', 'created_at'}
comment = IssueComment(id=42, body='hi', user='alice', created_at='2024-01-01T00:00:00Z')
assert comment.id == 42
try:
    comment.id = 99
    assert False
except dataclasses.FrozenInstanceError:
    pass

from afissues.labels import LabelSpec
import dataclasses
assert dataclasses.is_dataclass(LabelSpec)
fields = {f.name for f in dataclasses.fields(LabelSpec)}
assert fields == {'name', 'color', 'description'}
label = LabelSpec(name='af:fix', color='0075ca', description='Fix issue')
assert label.name == 'af:fix'
try:
    label.name = 'other'
    assert False
except dataclasses.FrozenInstanceError:
    pass

from afissues.errors import AfIssuesError
err = AfIssuesError('test message', key='val', other=42)
assert str(err) == 'test message'
assert err.context == {'key': 'val', 'other': 42}
err_empty = AfIssuesError()
assert err_empty.context == {}

source = read_file('packages/afissues/afissues/errors.py')
for pkg in ['agentfox', 'afspec', 'afaudit', 'nightshift']:
    assert pkg not in source, f'Found workspace import: {pkg}'

workspace_pkgs = ['agentfox', 'afspec', 'afaudit', 'nightshift']
source_files = glob('packages/afissues/afissues/**/*.py', recursive=True)
for path in source_files:
    content = read_file(path)
    for pkg in workspace_pkgs:
        assert pkg not in content, f'Found workspace package {pkg} in {path}'

edge_case_tests.assertion_pseudocode:
from afissues.protocol import NullPlatform
import asyncio
np = NullPlatform()
try:
    asyncio.run(np.create_pr(title='t', body='b', head='h', base='main'))
    assert False, 'Expected NotImplementedError'
except NotImplementedError as e:
    pass  # correct behavior
except Exception as e:
    assert False, f'Wrong exception type: {type(e)}'

from afissues.github import _validate_github_url
from afissues.errors import ConfigError
private_urls = [
    'http://192.168.1.1/api',
    'http://10.0.0.1/',
    'http://172.16.0.1/repo',
    'http://localhost/api',
]
for url in private_urls:
    try:
        _validate_github_url(url)
        assert False, f'Expected ConfigError for {url}'
    except ConfigError as e:
        assert str(e) != '', f'ConfigError should have descriptive message for {url}'
    except Exception as e:
        assert False, f'Wrong exception type {type(e)} for {url}'
